{"id":"gen-1792745268-K61JVxOlfnLVK9VFbpbK","object":"chat.completion","created":1792745268,"model":"openai/gpt-6-luna","provider":"OpenAI","system_fingerprint":null,"service_tier":"default","choices":[{"index":0,"logprobs":null,"finish_reason":"stop","native_finish_reason":"completed","message":{"role":"assistant","content":"{
